import {stageLabels,stages} from './commerce-model.mjs';
import {orderRows,filterOrders,orderReport,ordersCSV,downloadCSV,returnLabels} from './owner-model.mjs';
const money=p=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:2}).format((p||0)/100);
export function createOwnerOrders({api,isAPI,getState,commit,esc,toast}){
 let filters={},offset=0,container,loading=false;
 const input=(label,name,value='',extra='')=>`<label>${label}<input name="${name}" value="${esc(value)}" ${extra}></label>`;
 const select=(label,name,choices,value='')=>`<label>${label}<select name="${name}">${choices.map(([key,text])=>`<option value="${key}" ${value===key?'selected':''}>${text}</option>`).join('')}</select></label>`;
 async function localMutation(id,action,b){
  const next=structuredClone(getState()),o=next.demoOrders.find(o=>o.id===id);if(!o)throw Error('Order not found.');
  if(action==='shipment'){Object.assign(o,{courier_name:b.courier,shipment_id:b.shipmentId,tracking_url:b.trackingUrl});}
  else if(action==='aftercare'){Object.assign(o,{return_status:b.status,return_note:b.note,refund_amount_paise:b.status==='refund_recorded'?b.amountPaise:0,refund_reference:b.status==='refund_recorded'?b.reference:''});}
  o.ops_revision=(o.ops_revision||1)+1;if(!commit(next))throw Error('Could not save this order.');
 }
 async function render(target=container){
  if(loading)return;container=target;loading=true;container.setAttribute('aria-busy','true');
  try{
   const query=new URLSearchParams({...filters,offset:String(offset)});let data;
   if(isAPI)data=await api('/api/admin/orders?'+query);
   else{const all=filterOrders(orderRows(getState().demoOrders||[]),filters).sort((a,b)=>b.created_at-a.created_at);data={orders:all.slice(offset,offset+50),report:orderReport(all),total:all.length,limit:50};}
   if(offset&&offset>=data.total){offset=0;loading=false;return render();}
   const r=data.report;container.innerHTML=`<div class="notice">Order management · Reports show recorded payments, not profit or bank settlements.</div><div class="admin-stats owner-metrics"><div class="stat"><b>${r.orders}</b><span>Filtered orders</span></div><div class="stat"><b>${r.paidOrders}</b><span>Payment confirmed</span></div><div class="stat"><b>${money(r.collectedPaise)}</b><span>Recorded collections · includes delivery</span></div><div class="stat"><b>${money(r.recordedRefundPaise)}</b><span>Refunds recorded externally</span></div></div><p class="fineprint">Delivery collected: ${money(r.deliveryPaise)}. Payment fees, product costs and outside sales are not included in these reports.</p><form id="order-filters" class="owner-filter-grid">${input('Search orders / customer / perfume','q',filters.q,'type="search" maxlength="100"')}${select('Order status','status',[['','All stages'],...Object.entries(stageLabels).map(([k,v])=>[k,v])],filters.status)}${select('Payment','payment',[['','Any payment'],['pending','Pending'],['captured','Confirmed'],['captured_unallocated','Needs review']],filters.payment)}${select('Method','method',[['','Both methods'],['manual_upi','Direct UPI'],['razorpay','Razorpay']],filters.method)}${select('Returns','returns',[['','All returns'],...Object.entries(returnLabels)],filters.returns)}${input('From · India time','from',filters.from,'type="date"')}${input('Through','to',filters.to,'type="date"')}<div class="owner-filter-actions"><button class="btn" type="submit">Apply filters</button><button class="small-btn" type="button" data-op="clear">Clear</button><button class="small-btn" type="button" data-op="export">Export filtered CSV</button></div></form><p class="fineprint" aria-live="polite">${data.total?offset+1:0}–${Math.min(offset+50,data.total)} of ${data.total} orders. Exports contain customer details; share them only with authorised staff.</p><div class="owner-order-list">${data.orders.map(card).join('')||'<div class="empty-state"><h3>No matching orders.</h3><p>Try another filter or date range.</p></div>'}</div><div class="owner-pagination"><button class="btn outline" data-op="prev" ${offset===0?'disabled':''}>Previous</button><button class="btn outline" data-op="next" ${offset+50>=data.total?'disabled':''}>Next</button></div>`;
   container.querySelector('#order-filters').addEventListener('submit',e=>{e.preventDefault();filters=Object.fromEntries([...new FormData(e.currentTarget)].filter(([,v])=>v));if(filters.from&&filters.to&&filters.from>filters.to)return toast('Start date must be before end date.');offset=0;render().catch(e=>toast(e.message));});
   container.querySelectorAll('[data-op]').forEach(button=>button.addEventListener('click',async()=>{const action=button.dataset.op;try{
    if(action==='clear'){filters={};offset=0;await render();}if(action==='next'||action==='prev'){offset+=action==='next'?50:-50;await render();}
    if(action==='export'){button.disabled=true;let csv;if(isAPI){const response=await fetch('/api/admin/orders/export?'+new URLSearchParams(filters),{credentials:'same-origin',signal:AbortSignal.timeout(30000)});if(!response.ok){let d;try{d=await response.json()}catch{}throw Error(d?.error||'Export failed.');}csv=await response.text();}else csv=ordersCSV(filterOrders(orderRows(getState().demoOrders||[]),filters));downloadCSV(csv,'drip-dusk-orders.csv');}
   }catch(e){toast(e.message)}finally{button.disabled=false;}}));
   container.querySelectorAll('[data-operation]').forEach(form=>form.addEventListener('submit',async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(form)),id=form.dataset.id,action=form.dataset.operation,button=form.querySelector('button[type=submit]');button.disabled=true;try{
    const payload={...b,expectedRevision:Number(form.dataset.revision),checkedBank:b.checkedBank==='on',completedExternally:b.completedExternally==='on'};
    if(action==='approve-payment')payload.amountPaise=Math.round(Number(b.amount)*100);
    if(action==='aftercare'){payload.amountPaise=Math.round(Number(b.amount||0)*100);if(!b.note?.trim())throw Error('Enter a reason or update.');if(b.status==='refund_recorded'&&(!payload.completedExternally||!b.reference?.trim()||payload.amountPaise<1||payload.amountPaise>Number(form.dataset.total)))throw Error('Confirm the external refund and enter a valid reference and amount.');}
    if(action==='shipment'){if(!!b.courier!==!!b.shipmentId)throw Error('Enter both courier and AWB.');if(b.trackingUrl){const u=new URL(b.trackingUrl);if(u.protocol!=='https:'||u.username||u.password)throw Error('Use an HTTPS courier link.');}}
    if(isAPI)await api('/api/admin/orders/'+id+'/'+action,{method:['shipment','aftercare'].includes(action)?'PUT':'POST',body:payload});else await localMutation(id,action,payload);
    toast(action==='aftercare'?'Aftercare record saved. No money was moved and stock was not changed.':'Order saved.');await render();
   }catch(e){form.querySelector('[role=alert]').textContent=e.message;}finally{button.disabled=false;}}));
  }catch(e){throw e}finally{loading=false;container.removeAttribute('aria-busy');}
 }
 function card(o){const paid=o.payment_status==='captured',next={confirmed:'packed',packed:'shipped',shipped:'delivered'}[o.status],track=o.trackingPath||'#track/'+o.id+'/'+o.token;
  const form=(action,title,body)=>`<details class="owner-operation"><summary>${title}</summary><form data-operation="${action}" data-id="${esc(o.id)}" data-revision="${o.ops_revision}" data-total="${o.totalPaise}">${body}<p class="form-error" role="alert"></p><button class="btn" type="submit">Save ${title.toLowerCase()}</button></form></details>`;
  return `<article class="admin-order"><div><p class="eyebrow">${esc(o.ref)}${o.mode==='live'?'':' · test order'}</p><h3>${esc(stageLabels[o.status]||o.status)}</h3><p>${esc(o.customer.name)} · ${esc(o.customer.phone)}<br>${esc([o.customer.line1,o.customer.line2,o.customer.city,o.customer.state,o.customer.postcode].filter(Boolean).join(', '))}</p><p>${o.lines.map(l=>esc(l.name)+' × '+l.qty).join(' · ')}</p><span>${money(o.totalPaise)} · ${esc(new Date(o.created_at).toLocaleString('en-IN'))}</span><p>${esc(o.payment_method==='razorpay'?'Razorpay':'Direct UPI')} · ${esc(o.payment_status)}</p>${o.payment_reference?`<p>Reference: ${esc(o.payment_reference)}</p>`:''}<a class="text-link" href="${esc(track)}">Open private tracking <svg class=ui-icon aria-hidden=true focusable=false><use href=#arrow-up-right-icon></use></svg></a>${o.shipment_id?`<p>${esc(o.courier_name)} · AWB ${esc(o.shipment_id)}</p>`:''}${o.return_status!=='none'?`<p class="status-pill">${esc(returnLabels[o.return_status])}</p>`:''}</div><div class="admin-order-actions">${isAPI&&o.payment_method==='manual_upi'&&['pending','awaiting_verification'].includes(o.status)?form('approve-payment','Payment approval',`${input('Bank receipt reference','bankReference','','required pattern="[A-Za-z0-9-]{6,40}"')}${input('Amount received (₹)','amount',o.totalPaise/100,'type="number" min="1" step="0.01" required')}<label class="checkout-consent"><input name="checkedBank" type="checkbox" required> I checked my bank / UPI app and the full amount was received.</label>`)+`<form data-operation="cancel" data-id="${esc(o.id)}"><p class="form-error" role="alert"></p><button class="small-btn" type="submit">Cancel unpaid order</button></form>`:''}${next?`<button class="btn" data-action="order-server-pack" data-id="${esc(o.id)}" data-stage="${next}">Mark ${stageLabels[next].toLowerCase()}</button>`:''}${paid?form('shipment','Shipment details',`${input('Courier name','courier',o.courier_name,'maxlength="80"')}${input('AWB / shipment number','shipmentId',o.shipment_id,'maxlength="100" pattern="[A-Za-z0-9_-]+"')}${input('Courier tracking link · optional','trackingUrl',o.tracking_url,'type="url" maxlength="500"')}<p class="fineprint">Saved details appear in private customer tracking. This does not book a shipment.</p>`)+form('aftercare','Return / refund record',`${select('Request status','status',Object.entries(returnLabels),o.return_status)}<label>Reason / internal update<textarea name="note" maxlength="2000" required>${esc(o.return_note)}</textarea></label>${input('Refund amount (₹) · if completed','amount',o.refund_amount_paise?o.refund_amount_paise/100:'','type="number" min="0.01" step="0.01"')}${input('External refund reference','reference',o.refund_reference,'maxlength="160"')}<label class="checkout-consent"><input type="checkbox" name="completedExternally" ${o.return_status==='refund_recorded'?'checked':''}> Refund already completed in bank / Razorpay.</label><p class="fineprint">Internal record only. No refund is initiated, and returned stock is not automatically restocked.</p>`)+`<button class="text-link" data-action="order-message-preview" data-path="${esc(track)}" data-ref="${esc(o.ref)}">Preview WhatsApp confirmation <svg class=ui-icon aria-hidden=true focusable=false><use href=#arrow-up-right-icon></use></svg></button>`:''}</div></article>`;
 }
 return {render};
}
